/* STM32CubeU5 HAL SPI full-duplex transfer by GPDMA.
 *
 * Unmodified HAL. SPI1 is master, full duplex, software NSS, 8-bit frames, with a loopback slave
 * attached by the robot test. GPDMA1 channel 0 serves SPI1_TX (memory to peripheral) and
 * channel 1 serves SPI1_RX (peripheral to memory), in normal mode, as generated by STM32CubeMX.
 * Checks: HAL_SPI_TransmitReceive_DMA of 16 bytes ends with HAL_SPI_TxRxCpltCallback and the
 * received buffer equals the sent one. */

#include <string.h>

#include "clock_160mhz.h"

SPI_HandleTypeDef hspi1;
DMA_HandleTypeDef hdmaTx;
DMA_HandleTypeDef hdmaRx;

volatile uint32_t step;
volatile uint32_t failedStep;
volatile uint32_t transferComplete;
volatile uint32_t transferError;
volatile uint32_t dataOk;

static uint8_t txData[16];
static uint8_t rxData[16];

void SysTick_Handler(void)
{
    HAL_IncTick();
}

void GPDMA1_Channel0_IRQHandler(void)
{
    HAL_DMA_IRQHandler(&hdmaTx);
}

void GPDMA1_Channel1_IRQHandler(void)
{
    HAL_DMA_IRQHandler(&hdmaRx);
}

void SPI1_IRQHandler(void)
{
    HAL_SPI_IRQHandler(&hspi1);
}

void HAL_SPI_TxRxCpltCallback(SPI_HandleTypeDef *hspi)
{
    if (hspi == &hspi1)
    {
        transferComplete = 1u;
    }
}

void HAL_SPI_ErrorCallback(SPI_HandleTypeDef *hspi)
{
    if (hspi == &hspi1)
    {
        transferError = 1u;
    }
}

static void check(HAL_StatusTypeDef status, uint32_t at)
{
    step = at;
    if (status != HAL_OK)
    {
        failedStep = at;
        for (;;)
        {
        }
    }
}

static void dmaInit(DMA_HandleTypeDef *hdma, DMA_Channel_TypeDef *instance, uint32_t request,
                    uint32_t direction, uint32_t sourceIncrement, uint32_t destinationIncrement)
{
    hdma->Instance = instance;
    hdma->Init.Request = request;
    hdma->Init.BlkHWRequest = DMA_BREQ_SINGLE_BURST;
    hdma->Init.Direction = direction;
    hdma->Init.SrcInc = sourceIncrement;
    hdma->Init.DestInc = destinationIncrement;
    hdma->Init.SrcDataWidth = DMA_SRC_DATAWIDTH_BYTE;
    hdma->Init.DestDataWidth = DMA_DEST_DATAWIDTH_BYTE;
    hdma->Init.Priority = DMA_LOW_PRIORITY_HIGH_WEIGHT;
    hdma->Init.SrcBurstLength = 1;
    hdma->Init.DestBurstLength = 1;
    hdma->Init.TransferAllocatedPort = DMA_SRC_ALLOCATED_PORT0 | DMA_DEST_ALLOCATED_PORT1;
    hdma->Init.TransferEventMode = DMA_TCEM_BLOCK_TRANSFER;
    hdma->Init.Mode = DMA_NORMAL;
    if (HAL_DMA_Init(hdma) != HAL_OK)
    {
        failedStep = 100;
        for (;;)
        {
        }
    }
}

void HAL_SPI_MspInit(SPI_HandleTypeDef *hspi)
{
    if (hspi->Instance != SPI1)
    {
        return;
    }
    __HAL_RCC_SPI1_CLK_ENABLE();
    __HAL_RCC_GPDMA1_CLK_ENABLE();

    dmaInit(&hdmaTx, GPDMA1_Channel0, GPDMA1_REQUEST_SPI1_TX, DMA_MEMORY_TO_PERIPH,
            DMA_SINC_INCREMENTED, DMA_DINC_FIXED);
    __HAL_LINKDMA(hspi, hdmatx, hdmaTx);
    dmaInit(&hdmaRx, GPDMA1_Channel1, GPDMA1_REQUEST_SPI1_RX, DMA_PERIPH_TO_MEMORY,
            DMA_SINC_FIXED, DMA_DINC_INCREMENTED);
    __HAL_LINKDMA(hspi, hdmarx, hdmaRx);

    HAL_NVIC_SetPriority(GPDMA1_Channel0_IRQn, 1, 0);
    HAL_NVIC_EnableIRQ(GPDMA1_Channel0_IRQn);
    HAL_NVIC_SetPriority(GPDMA1_Channel1_IRQn, 1, 0);
    HAL_NVIC_EnableIRQ(GPDMA1_Channel1_IRQn);
    HAL_NVIC_SetPriority(SPI1_IRQn, 1, 0);
    HAL_NVIC_EnableIRQ(SPI1_IRQn);
}

int main(void)
{
    check(HAL_Init(), 1);
    check(SystemClockConfig160MHz(), 2);

    hspi1.Instance = SPI1;
    hspi1.Init.Mode = SPI_MODE_MASTER;
    hspi1.Init.Direction = SPI_DIRECTION_2LINES;
    hspi1.Init.DataSize = SPI_DATASIZE_8BIT;
    hspi1.Init.CLKPolarity = SPI_POLARITY_LOW;
    hspi1.Init.CLKPhase = SPI_PHASE_1EDGE;
    hspi1.Init.NSS = SPI_NSS_SOFT;
    hspi1.Init.BaudRatePrescaler = SPI_BAUDRATEPRESCALER_16;
    hspi1.Init.FirstBit = SPI_FIRSTBIT_MSB;
    hspi1.Init.TIMode = SPI_TIMODE_DISABLE;
    hspi1.Init.CRCCalculation = SPI_CRCCALCULATION_DISABLE;
    hspi1.Init.CRCPolynomial = 0x7;
    hspi1.Init.NSSPMode = SPI_NSS_PULSE_DISABLE;
    hspi1.Init.NSSPolarity = SPI_NSS_POLARITY_LOW;
    hspi1.Init.FifoThreshold = SPI_FIFO_THRESHOLD_01DATA;
    hspi1.Init.MasterSSIdleness = SPI_MASTER_SS_IDLENESS_00CYCLE;
    hspi1.Init.MasterInterDataIdleness = SPI_MASTER_INTERDATA_IDLENESS_00CYCLE;
    hspi1.Init.MasterReceiverAutoSusp = SPI_MASTER_RX_AUTOSUSP_DISABLE;
    hspi1.Init.MasterKeepIOState = SPI_MASTER_KEEP_IO_STATE_DISABLE;
    hspi1.Init.IOSwap = SPI_IO_SWAP_DISABLE;
    hspi1.Init.ReadyMasterManagement = SPI_RDY_MASTER_MANAGEMENT_INTERNALLY;
    hspi1.Init.ReadyPolarity = SPI_RDY_POLARITY_HIGH;
    check(HAL_SPI_Init(&hspi1), 3);

    for (uint32_t index = 0u; index < sizeof(txData); ++index)
    {
        txData[index] = (uint8_t)(0x30u + index * 7u);
    }
    check(HAL_SPI_TransmitReceive_DMA(&hspi1, txData, rxData, sizeof(txData)), 4);
    const uint32_t start = HAL_GetTick();
    while (!transferComplete && !transferError)
    {
        if (HAL_GetTick() - start > 100u)
        {
            failedStep = 5;
            for (;;)
            {
            }
        }
    }
    dataOk = memcmp(txData, rxData, sizeof(txData)) == 0;

    step = 6;
    for (;;)
    {
    }
}
